SELECT id, symbol, interval_code, candle_open_time, decision, original_decision, generated_at, created_at FROM crypto_ai.trade_signal WHERE id IN (156852,166821,168277,172201,172588,176934) ORDER BY id;
SELECT symbol, id, observed_at, price, delivery_status, created_at FROM crypto_ai.market_price_event WHERE (symbol='EGLDUSDT' AND observed_at BETWEEN '2026-10-11 20:59:59' AND '2026-10-11 21:00:13') OR (symbol='XRPUSDT' AND observed_at BETWEEN '2026-10-12 03:29:59' AND '2026-10-12 03:30:07') OR (symbol='ACEUSDT' AND observed_at BETWEEN '2026-10-12 10:04:58' AND '2026-10-12 10:05:21') ORDER BY symbol, observed_at LIMIT 60;